mapper.select:
SELECT 'tb_member' AS tableName, COUNT(*) AS total FROM tb_member WHERE delete_yn = 'N'
AND site_id = #{siteId}
UNION ALL SELECT 'tb_member_dormant' AS tableName, COUNT(*) AS total FROM tb_member_dormant WHERE 1 = 1
AND site_id = #{siteId}
UNION ALL SELECT 'tb_member_withdraw' AS tableName, COUNT(*) AS total FROM tb_member_withdraw WHERE retention_expire_at > CURRENT_TIMESTAMP
AND site_id = #{siteId}

SELECT CASE WHEN birth_year IS NULL OR birth_year NOT REGEXP '^[0-9]{4}$' THEN 'UNKNOWN' WHEN YEAR(NOW()) - CAST(birth_year AS UNSIGNED) >= 60 THEN '60+' WHEN YEAR(NOW()) - CAST(birth_year AS UNSIGNED) >= 50 THEN '50' WHEN YEAR(NOW()) - CAST(birth_year AS UNSIGNED) >= 40 THEN '40' WHEN YEAR(NOW()) - CAST(birth_year AS UNSIGNED) >= 30 THEN '30' WHEN YEAR(NOW()) - CAST(birth_year AS UNSIGNED) >= 20 THEN '20' WHEN YEAR(NOW()) - CAST(birth_year AS UNSIGNED) >= 10 THEN '10' ELSE 'CHILD' END AS ageBucket, COUNT(*) AS total FROM tb_member WHERE delete_yn = 'N'
AND site_id = #{siteId}
GROUP BY ageBucket ORDER BY ageBucket

SELECT COALESCE(NULLIF(gender, ''), 'UNKNOWN') AS gender, COUNT(*) AS total FROM tb_member WHERE delete_yn = 'N'
AND site_id = #{siteId}
GROUP BY gender ORDER BY gender

SELECT o.provider AS provider, COUNT(*) AS total FROM tb_member_oauth o JOIN tb_member m ON m.member_id = o.member_id WHERE o.delete_yn = 'N' AND o.use_yn = 'Y' AND m.delete_yn = 'N'
AND m.site_id = #{siteId}
GROUP BY o.provider ORDER BY total DESC

SELECT COALESCE(NULLIF(withdraw_status, ''), 'UNKNOWN') AS withdrawStatus, COUNT(*) AS total FROM tb_member_withdraw WHERE retention_expire_at > CURRENT_TIMESTAMP
AND site_id = #{siteId}
GROUP BY withdrawStatus ORDER BY total DESC

SELECT DATE(created_at) AS statDate, COUNT(*) AS joinCount FROM tb_member WHERE delete_yn = 'N' AND created_at >= #{from} AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
AND site_id = #{siteId}
GROUP BY DATE(created_at) ORDER BY statDate

SELECT DATE(created_at) AS statDate, COUNT(*) AS dormantCount FROM tb_member_dormant WHERE created_at >= #{from} AND created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
AND site_id = #{siteId}
GROUP BY DATE(created_at) ORDER BY statDate

SELECT DATE(withdraw_at) AS statDate, COUNT(*) AS withdrawCount FROM tb_member_withdraw WHERE withdraw_at >= #{from} AND withdraw_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
AND site_id = #{siteId}
GROUP BY DATE(withdraw_at) ORDER BY statDate
